// spec: specs/matchmaker.md (раздел 1.3)
// seed: tests/seed.free.spec.ts
// Расхождения плана с живой страницей (19.11.2026):
//  - поле «טלפון» открывается УЖЕ ЗАПОЛНЕННЫМ номером из профиля (050-000-0001): для шага «телефон пустой» тест сначала очищает поле;
//  - есть подзаголовок «ליווי אישי של שדכנית אנושית» и подсказка «לאיזה מספר השדכנית תחזור אליך? אפשר לעדכן לפני השליחה.»;
//  - placeholder поля времени: «למשל: בערבים אחרי 19:00»; поле заметки без видимой подписи, accessible name «משהו שחשוב שהשדכנית תדע? (לא חובה)»;
//  - имя RPC создания заявки на живой странице не наблюдалось (создать заявку = нарушить правила), поэтому отслеживаем POST-запросы, чьи URL содержат matchmaker/checkout/payment/order.
// Корректный номер НЕ вводится; «אישור ושליחת הבקשה» нажимается только с пустым и с невалидным «12-34».
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/free-r13.json'),
  colorScheme: 'dark',
});

test.describe('שדכנית אישית (#3a3cb9 #58614c)', () => {
  test('Форма: пусто/«12-34» → сообщения, заявка не уходит @iphone @prod-safe', async ({ page }) => {
    const createRequests: string[] = [];
    page.on('request', (req) => {
      if (req.method() === 'POST' && /matchmaker|checkout|payment|order/i.test(req.url())) createRequests.push(req.url());
    });

    // 1. Экран услуги → «להתחיל — ₪249.90»
    await page.goto('/settings');
    await page.getByRole('button', { name: 'השידוך שלי' }).click();
    await expect(page).toHaveURL(/\/matchmaker$/);
    await page.getByRole('button', { name: 'להתחיל — ₪249.90' }).click();

    await expect(page.getByText('פרטי קשר', { exact: true })).toBeVisible();
    const phone = page.getByRole('textbox', { name: 'טלפון', exact: true });
    await expect(phone).toBeVisible();
    await expect(phone).toHaveAttribute('placeholder', '050-000-0000');
    await expect(page.getByRole('textbox', { name: 'זמן נוח לשיחה (לא חובה)' })).toBeVisible();
    await expect(page.getByRole('textbox', { name: /^משהו שחשוב שהשדכנית תדע/ })).toBeVisible();
    await expect(page.getByText('שדכנית אישית', { exact: true })).toBeVisible();
    await expect(page.getByText('₪249.90', { exact: true })).toBeVisible();
    await expect(page.getByText('תשלום חד־פעמי', { exact: true })).toBeVisible();
    const submit = page.getByRole('button', { name: 'אישור ושליחת הבקשה' });
    await expect(submit).toBeVisible();

    // 2. Телефон пустой → «אישור ושליחת הבקשה»
    await phone.fill('');
    await submit.click();
    await expect(page.getByText('צריך מספר טלפון כדי שהשדכנית תחזור אליך')).toBeVisible();
    await expect(page.getByText('פרטי קשר', { exact: true })).toBeVisible();

    // 3. Ввести «12-34» → «אישור ושליחת הבקשה»
    await phone.fill('12-34');
    await submit.click();
    await expect(page.getByText('מספר הטלפון לא תקין')).toBeVisible();
    await expect(page.getByText('פרטי קשר', { exact: true })).toBeVisible();
    await expect(page.getByText('הבקשה התקבלה')).toBeHidden();
    await expect(page.getByText('לתשלום — ₪249.90')).toBeHidden();

    // Заявка не уходит
    expect(createRequests).toHaveLength(0);
  });
});
